const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // --- Helper Functions ---
  const getOzoneHoleArea = (startDate, endDate, geometry) => {
    const DU_CONVERSION_FACTOR = 2241.15;
    const OZONE_HOLE_THRESHOLD_DU = 220;

    // Load the Sentinel-5P OFFLINE Ozone collection
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select(['O3_column_number_density', 'qa_value']);

    // Check if the collection is empty
    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { area: null, images: 0, valid_pixels: null, error: 'C1' };
    }

    // Process the collection
    const composite = collection
      .map(image => image.updateMask(image.select('qa_value').gt(0.5)))
      .mean();

    // Convert to Dobson Units and create a binary mask for the ozone hole
    const ozoneDU = composite.select('O3_column_number_density').multiply(DU_CONVERSION_FACTOR);
    const ozoneHoleMask = ozoneDU.lt(OZONE_HOLE_THRESHOLD_DU);

    // Calculate the area of the ozone hole
    // We multiply the binary mask by the area of each pixel.
    const areaImage = ozoneHoleMask.multiply(ee.Image.pixelArea());

    const stats = areaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10000, // Use a coarse scale for this large area to avoid timeout
      maxPixels: 1e12
    });

    const area = stats.get('O3_column_number_density');

    // Check for valid pixels
    const pixelCount = ozoneHoleMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 10000,
        maxPixels: 1e12
    }).get('O3_column_number_density');

    return { area: area, images: collectionSize, valid_pixels: pixelCount, error: null };
  };

  // 1. Geometry & Time Definitions
  const antarctica = ee.Geometry.Point([0, -90]).buffer(4e6); // ~4000km radius around South Pole
  const period1_start = '2024-08-26';
  const period1_end = '2024-08-31'; // Exclusive end date
  const period2_start = '2024-09-26';
  const period2_end = '2024-10-01'; // Exclusive end date

  // 2. Data Acquisition & Processing
  const augustData = getOzoneHoleArea(period1_start, period1_end, antarctica);
  const septemberData = getOzoneHoleArea(period2_start, period2_end, antarctica);

  // 3. Validation & Final Answer
  if (augustData.error === 'C1' || septemberData.error === 'C1') {
    console.log(`August 2024 Images: ${augustData.images}`);
    console.log(`September 2024 Images: ${septemberData.images}`);
    console.log("Evidence: No images found for one or both future date ranges.");
    console.log("A: No");
    return;
  }

  const augustArea = augustData.area.getInfo();
  const septemberArea = septemberData.area.getInfo();
  const augustPixels = augustData.valid_pixels.getInfo();
  const septemberPixels = septemberData.valid_pixels.getInfo();

  console.log(`Aug 2024 Ozone Hole Area (km^2): ${augustArea ? (augustArea / 1e6).toFixed(0) : 'N/A'}`);
  console.log(`Aug 2024 Valid Pixels: ${augustPixels}`);
  console.log(`Sep 2024 Ozone Hole Area (km^2): ${septemberArea ? (septemberArea / 1e6).toFixed(0) : 'N/A'}`);
  console.log(`Sep 2024 Valid Pixels: ${septemberPixels}`);

  if (augustArea === null || septemberArea === null) {
      console.log("Evidence: Area calculation failed, result is null.");
      console.log("C3");
      return;
  }

  if (augustPixels === 0 || septemberPixels === 0) {
      console.log("Evidence: No valid pixels remained after QA filtering for one or both periods.");
      console.log("C2");
      return;
  }

  console.log(`Evidence: Comparing Sep area (${(septemberArea / 1e6).toFixed(0)} km^2) with Aug area (${(augustArea / 1e6).toFixed(0)} km^2).`);

  if (septemberArea > augustArea) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
